def encrypt(s):
    result = []
    for char in s:
        if char.isalpha():
            base = ord('a') if char.islower() else ord('A')
            result.append(chr((ord(char) - base + 4) % 26 + base))
        else:
            result.append(char)
    return ''.join(result)
